import { gsap } from 'gsap';

// Get random value between min and max
const getRandomValue = (min, max) => {
  return min + Math.random() * (max - min);
};

// Get random boolean based on probability
const getRandomBool = probability => {
  return Math.random() < probability;
};

// Get a random sign (+1 or -1)
const getRandomSign = () => {
  return Math.random() > 0.5 ? 1 : -1;
};

// Get typing pause with natural irregularities (occasionally longer)
const getTypingPause = () => {
  // 85% of the time, use normal range
  if (Math.random() < 0.85) {
    return getRandomValue(0.01, 0.12); // 10-120ms range
  }
  // 15% of the time, use a longer pause (120-300ms)
  return getRandomValue(0.12, 0.3);
};

// Global tracking of animated elements to prevent double animation
const animatedElements = new Set();

/**
 * Clear all animations and reset the DOM to its original state
 */
const clearAllAnimations = () => {
  // Kill all GSAP animations to prevent conflicts
  gsap.killTweensOf('.gsap-char');

  // Find and remove all overlays
  const overlays = document.querySelectorAll('.gsap-overlay');
  overlays.forEach(overlay => {
    const parent = overlay.parentElement;
    if (parent) {
      parent.removeChild(overlay);
      parent.classList.remove('gsap-has-overlay');
    }
  });

  // Clear the tracking set
  animatedElements.clear();
};

/**
 * Split text into spans for animation
 * @param {HTMLElement} element - Element containing text to split
 * @returns {HTMLSpanElement[]} Array of span elements
 */
const splitTextIntoSpans = element => {
  if (!element || !element.textContent) return [];

  // Store original element properties
  const originalHTML = element.innerHTML;
  const computedStyle = window.getComputedStyle(element);

  // Create a style object with all important text properties
  const styleProperties = {
    color: computedStyle.color,
    fontSize: computedStyle.fontSize,
    fontWeight: computedStyle.fontWeight,
    fontFamily: computedStyle.fontFamily,
    fontStyle: computedStyle.fontStyle,
    textDecoration: computedStyle.textDecoration,
    letterSpacing: computedStyle.letterSpacing,
    lineHeight: computedStyle.lineHeight,
    textTransform: computedStyle.textTransform
  };

  // Save original text and create a wrapper
  const text = element.textContent;
  const wrapper = document.createElement('span');
  wrapper.classList.add('gsap-text-wrapper');
  wrapper.style.display = 'inline-block';
  wrapper.dataset.originalHtml = originalHTML;

  // Create spans for each character
  const spans = [];
  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    const span = document.createElement('span');
    span.textContent = char === ' ' ? '\u00A0' : char; // Use non-breaking space for spaces
    span.style.display = 'inline-block';
    span.style.opacity = '0';
    span.classList.add('gsap-char');

    // Apply all preserved style properties
    Object.entries(styleProperties).forEach(([property, value]) => {
      if (value) {
        span.style[property] = value;
      }
    });

    // Add special effects to occasional characters (much lower probability)
    if (getRandomBool(0.06)) {
      span.classList.add('gsap-char-flicker');
    }
    if (getRandomBool(0.04)) {
      span.classList.add('gsap-char-glow');
    }
    wrapper.appendChild(span);
    spans.push(span);
  }

  // Replace element content with our spans
  element.innerHTML = '';
  element.appendChild(wrapper);
  return spans;
};

