  if (!element) return;

  // Remove from tracking set
  animatedElements.delete(element);
  const wrapper = element.querySelector('.gsap-text-wrapper');
  if (wrapper && wrapper.dataset.originalHtml) {
    // Kill any animations on this element's characters
    const chars = element.querySelectorAll('.gsap-char');
    if (chars.length) {
      gsap.killTweensOf(chars);
    }

    // Restore original HTML
    element.innerHTML = wrapper.dataset.originalHtml;
  }
};

/**
