 * @param {HTMLElement} element - Element to animate
 * @param {Object} options - Animation options
 */
export const animateText = (element, options = {}) => {
  if (!element) return;
  const defaults = {
    staggerRange: [0.01, 0.12],
    // Wider range for typing irregularity (10-120ms)
    duration: 0.2,
    // Quick appearance for each character
    opacityDuration: 0.35,
    // Longer, softer fade for opacity
    ease: "power2.out",
    // General easing
    opacityEase: "sine.inOut",
    // Softer ease-in-ease-out for opacity
    delay: 0,
    blur: 2,
    // Subtle blur
    y: 2,
    // Subtle movement
    cleanup: true
