  timeline.fromTo(spans, {
    filter: `blur(${settings.blur}px)`,
    y: settings.y
  }, {
    filter: "blur(0px)",
    y: 0,
    duration: settings.duration,
    ease: settings.ease,
    stagger: {
      each: staggerArray,
      from: "start",
      ease: "none"
    }
  }, 0);
